// Set Candidate Profile & Ingested Job Context
const input = $input.first().json;

const profile = {
  name: "Saurao Dalvi",
  email: "sauraodalvi97@gmail.com",
  phone: "+91 9876543210",
  title: "AI Product Manager / Associate Product Manager",
  linkedin: "https://www.linkedin.com/in/saurao-dalvi/",
  portfolio: "https://sauraodalvi.netlify.app/",
  experience_years: "3+",
  past_companies: "FlytBase (Drone Tech B2B SaaS) & CrelioHealth (HealthTech SaaS)",
  core_strengths: "0-to-1 Product Management, LLM & AI Workflows, MRR Growth, Customer Discovery, Agile Leadership",
  target_locations: ["Pune", "European Union", "Germany", "Netherlands", "UK", "Japan", "Singapore", "Indonesia", "Remote"]
};

const job = {
  company: input.company || "Target Company",
  role: input.role || "Product Manager",
  location: input.location || "Remote / Global",
  url: input.url || input.apply_url || "",
  description: input.description || "",
  contact_name: input.contact_name || "Hiring Team",
  contact_email: input.contact_email || ""
};

// Generate 1-Click LinkedIn Search Query for Referrers
const cleanCompany = job.company.replace(/[^a-zA-Z0-9 ]/g, "").trim();
const linkedinSearchUrl = `https://www.linkedin.com/search/results/people/?keywords=${encodeURIComponent(cleanCompany + ' Product Manager')}&origin=GLOBAL_SEARCH_HEADER`;

return {
  json: {
    profile,
    job,
    linkedinSearchUrl,
    timestamp: new Date().toISOString()
  }
};

// Parse AI Output into Clean Referral Packet
let aiRaw = $input.first().json.text || $input.first().json.content || "{}";
let parsed = {};

try {
  // Strip possible markdown fences
  aiRaw = aiRaw.replace(/```json/g, "").replace(/```/g, "").trim();
  parsed = JSON.parse(aiRaw);
} catch (e) {
  parsed = {
    stars: 5,
    fit_reason: "High strategic fit for AI Product Management",
    ats_score: 90,
    keywords: ["AI Product Management", "0-to-1 SaaS", "LLM Workflows", "MRR Growth"],
    linkedin_connect_note: `Hi [Name], saw your work at ${$node["Profile & Context Injector"].json.job.company}! Applying for ${$node["Profile & Context Injector"].json.job.role}. With 3+ yrs scaling 0-to-1 AI SaaS, my background maps closely. Open to passing my profile along for internal referral?`,
    forwardable_referral_blurb: `Candidate: Saurao Dalvi | Role: ${$node["Profile & Context Injector"].json.job.role}\nOverview: AI Product Manager with 3+ yrs scaling 0-to-1 B2B SaaS. Strong track record in LLM workflows and MRR growth.\nContact: sauraodalvi97@gmail.com | Portfolio: https://sauraodalvi.netlify.app/`,
    hiring_manager_cold_email: `Subject: Note regarding ${$node["Profile & Context Injector"].json.job.role} - Saurao Dalvi\n\nDear Hiring Team,\nI noticed ${$node["Profile & Context Injector"].json.job.company} is seeking a ${$node["Profile & Context Injector"].json.job.role}. As an AI PM with 3+ years experience driving 0-to-1 B2B SaaS products at FlytBase and CrelioHealth, I specialize in shipping LLM workflows and scaling MRR.`
  };
}

const merged = {
  ...$node["Profile & Context Injector"].json,
  referral_packet: parsed
};

return { json: merged };

